#!/usr/bin/env python3
"""Builds round 8's two folders from round 7's, each reused file checked by hash.

WHAT DECIDED IT

PHASE7_DECISIONS.md, "Decision, 4 October 2026 -- round 8's package: the
tag's, with only the instruction and the Part 7 document corrected; the
freeze holds" (Claude's, under Viktor's delegation of the next audit). Round
8 is sent what round 7 was, built from the tag `round7-sent-2026-09-30`
(`e186423`), with two documents changed: rev 9 of the instruction replaces
rev 8, and the Part 7 document is corrected.

WHY ROUND 7'S FILES AND NOT A NEW BUILD FROM THE TAG

How "built from the tag" is done is Claude's design, in the commit that adds
this file (PHASE7_DECISIONS.md, "Decision, 4 October 2026 -- round 8's
tooling"). A new build at the tag would not be the same bytes: the manifest
carries its build time, and the history file reads the repository as it is
when it runs -- its tags now include `round7-sent-2026-09-30`, which did not
exist when round 7 was built. Round 7's own files are the tag's build, and
both runs recorded every file's SHA-256 in their committed
turn1_run_metadata.json. So this script copies them, refuses unless each
hashes to what both runs recorded, and the auditor gets the bytes Laguna S
2.1 got, which is what keeps the four test bugs and their "Found means"
sentences pointing at the same lines.

The cost: round 7's built folders are ignored by git (.gitignore,
`docs/audit_package/round*/*`), so they exist only on the machine that built
them. If they are lost, this script refuses, and round 8 has to be rebuilt
from the tag some other way, with a new manifest the auditor sees.

WHAT GOES WHERE

MESSAGE1_PARTS1-6/  round 7's six files except rev 8, verified; rev 9 from
                    docs/audit_package/. Round 7's MANIFEST.md says "Round:
                    round7" and its build time; rev 9 says why.
MESSAGE2_PART7/     the Part 7 document from docs/audit_package/, refused
                    while it is still the tag's text (not yet corrected); and
                    the commit messages after e65a0f7 up to the tag only,
                    generated by build_audit_package.py's own function and
                    refused unless they hash to what round 7's build wrote.

Every folder holds exactly the files send_audit_round.py sends in that
message (tests/test_send_audit_round.py builds both and reads them back with
the send's own reader). The round directory also gets MANIFEST.md, which is
tracked (.gitignore keeps `round*/MANIFEST.md`) and records every file sent,
its SHA-256 and where it came from, and README.md, which is not.

Nothing is written until everything has been read and checked, so a refusal
leaves the folders as they were. It sends nothing and opens no network
connection.

Usage (from the repository root):

    python docs/build/build_round8_package.py
"""

import hashlib
import importlib.util
import json
import os
import shutil
import subprocess
import sys

REPO = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
PACKAGE_DIR = os.path.join(REPO, "docs", "audit_package")
REPORTS_DIR = os.path.join(REPO, "docs", "audit_reports")
ROUND = "round8"
OUT_DIR = os.path.join(PACKAGE_DIR, ROUND)
SOURCE_ROUND = "round7"
SOURCE_DIR = os.path.join(PACKAGE_DIR, SOURCE_ROUND)
MESSAGE1 = "MESSAGE1_PARTS1-6"
MESSAGE2 = "MESSAGE2_PART7"

TAG = "round7-sent-2026-09-30"
TAG_COMMIT = "e186423"

# Round 7's two runs. Both recorded the same first message (payload SHA-256
# 1b8b8095...), file by file.
SOURCE_RUNS = ("round7_laguna-s-2.1_2026-09-30", "round7_laguna-s-2.1_run2_2026-09-30")

SOURCE_INSTRUCTION = "item16_review_instruction_rev8.md"
INSTRUCTION = "item16_review_instruction_rev9.md"

# Round 7's first message without its instruction, as both runs recorded it:
# {file name: SHA-256}. In the send's order (send_audit_round.MESSAGE1_ATTACHMENTS).
REUSED = {
    "Phase7_Constitution_v1.0_RATIFIED_AUDITCOPY.txt":
        "08f663a3b591c50e9ac0c62a3512c2a96c00ffb5234a5ed40814c52015aea700",
    "phase7_engine_source.md":
        "d294caf35cbd944089ee037ce8a73eaf6d4c052012e0f0be99b149cf6895ad3a",
    "phase7_test_suite.md":
        "8f6a31bd3306d9e6225bb24c552473f7397e331bdd36b17413d6dafe9086a82e",
    "MANIFEST.md":
        "732e411b6ef26d1c67a97bcec971bfe4374bdaaa0fa8a8c55393dcc17d58e267",
    "version_control_history.md":
        "a68235cb3d9300aedbe1a90bdaa9a2bc5612b05ddaa5071b314c4b7177fdd057",
    "execution_transcripts.md":
        "62e313a6a8e4e73b7e166c5d426762bd81e312552f336d8fc9d859dc6e8cd292",
}

PART7_DOCUMENT = "part7_material_PART7_ONLY.md"
COMMIT_MESSAGES = "commit_messages_PART7_ONLY.md"
# What round 7's build wrote for the commits after e65a0f7 up to the tag (90
# of them), on Viktor's machine on 30 September 2026; the same bytes were
# regenerated from an autocrlf clone on Linux on 4 October 2026.
COMMIT_MESSAGES_SHA256 = "c23a6fed8f09c3adc8c68f3028d2b7c5c36b4e1b0af8d54111cf6a2b9ac676d9"


def _sha256(data):
    return hashlib.sha256(data).hexdigest()


def _read_bytes(path):
    with open(path, "rb") as fh:
        return fh.read()


def _builder():
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "build_audit_package.py")
    spec = importlib.util.spec_from_file_location("phase7_round8_builder", path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    module.REPO = REPO
    return module


def _git_show(rev_path):
    """A file's bytes as git holds them at a commit, or None."""
    try:
        out = subprocess.run(["git", "-C", REPO, "show", rev_path], capture_output=True)
    except OSError:
        return None
    return out.stdout if out.returncode == 0 else None


def recorded_files():
    """{run folder: {file name: SHA-256}} from round 7's committed run records."""
    found = {}
    for run in SOURCE_RUNS:
        path = os.path.join(REPORTS_DIR, run, "turn1_run_metadata.json")
        with open(path, encoding="utf-8") as fh:
            meta = json.load(fh)
        found[run] = {f["name"]: f["sha256"] for f in meta["files"]}
    return found


def check_reused():
    """Round 7's files, each checked. Returns ({name: bytes}, problems)."""
    problems = []
    try:
        records = recorded_files()
    except (OSError, ValueError, KeyError) as exc:
        return {}, [f"round 7's run records could not be read: {exc}"]
    for run, files in records.items():
        expected = dict(REUSED, **{SOURCE_INSTRUCTION: files.get(SOURCE_INSTRUCTION)})
        if files != expected:
            problems.append(f"{run}'s record does not list the files and hashes this "
                            "script reuses")
    folder = os.path.join(SOURCE_DIR, MESSAGE1)
    data = {}
    for name, digest in REUSED.items():
        path = os.path.join(folder, name)
        if not os.path.isfile(path):
            problems.append(f"{SOURCE_ROUND}/{MESSAGE1}/{name} is missing")
            continue
        raw = _read_bytes(path)
        if _sha256(raw) != digest:
            problems.append(f"{SOURCE_ROUND}/{MESSAGE1}/{name} is not the file round 7 "
                            f"sent: SHA-256 {_sha256(raw)}, recorded {digest}")
            continue
        data[name] = raw
    return data, problems


def check_part7_document():
    """The Part 7 document, refused while it is still the tag's text."""
    path = os.path.join(PACKAGE_DIR, PART7_DOCUMENT)
    if not os.path.isfile(path):
        return None, [f"{PART7_DOCUMENT} is not in docs/audit_package/"]
    raw = _read_bytes(path)
    at_tag = _git_show(f"{TAG}:docs/audit_package/{PART7_DOCUMENT}")
    if at_tag is None:
        return None, [f"{PART7_DOCUMENT} could not be read at {TAG} to compare with"]
    if raw.replace(b"\r\n", b"\n") == at_tag.replace(b"\r\n", b"\n"):
        return None, [f"{PART7_DOCUMENT} is still the text it had at {TAG}: it names round "
                      "7 as its own and is to be corrected first (round 8's preparation "
                      "list, item 4)"]
    return raw, []


def check_commit_messages():
    """The commit messages after e65a0f7 up to the tag, as round 7's build wrote them."""
    builder = _builder()
    try:
        text = builder._full_messages(since=builder.PART7_COMMITS_SINCE, until=TAG)
    except SystemExit as exc:
        return None, [str(exc)]
    raw = text.encode("utf-8")
    if _sha256(raw) != COMMIT_MESSAGES_SHA256:
        return None, [f"the commit messages up to {TAG} hash to {_sha256(raw)}, not "
                      f"{COMMIT_MESSAGES_SHA256}, the file round 7's build wrote"]
    return raw, []


def main():
    problems = []
    reused, found = check_reused()
    problems += found
    instruction_path = os.path.join(PACKAGE_DIR, INSTRUCTION)
    instruction = None
    if os.path.isfile(instruction_path):
        instruction = _read_bytes(instruction_path)
    else:
        problems.append(f"{INSTRUCTION} is not in docs/audit_package/ (round 8's "
                        "preparation list, item 4)")
    part7, found = check_part7_document()
    problems += found
    messages, found = check_commit_messages()
    problems += found
    if problems:
        sys.exit("REFUSING TO BUILD round 8. Nothing has been written.\n  "
                 + "\n  ".join(problems))

    message1 = {INSTRUCTION: instruction}
    message1.update(reused)
    message2 = {PART7_DOCUMENT: part7, COMMIT_MESSAGES: messages}
    sources = {INSTRUCTION: f"docs/audit_package/{INSTRUCTION}",
               PART7_DOCUMENT: f"docs/audit_package/{PART7_DOCUMENT} (corrected after {TAG})",
               COMMIT_MESSAGES: f"generated: the commits after e65a0f7 up to {TAG}, "
                                "the same bytes round 7's build wrote"}
    for name in REUSED:
        sources[name] = f"{SOURCE_ROUND}/{MESSAGE1}/{name}, as both round 7 runs sent it"

    for folder in (MESSAGE1, MESSAGE2):
        shutil.rmtree(os.path.join(OUT_DIR, folder), ignore_errors=True)
        os.makedirs(os.path.join(OUT_DIR, folder))
    lines = ["# round8 -- what is sent, file by file", "",
             f"Built by docs/build/build_round8_package.py from the files of {SOURCE_ROUND}/ "
             f"(the build of `{TAG_COMMIT}`, tagged `{TAG}`), checked against the "
             "hashes round 7's two runs recorded, with only the instruction and the "
             "Part 7 document replaced. Each line: size in bytes, SHA-256, file, source.", ""]
    for folder, files in ((MESSAGE1, message1), (MESSAGE2, message2)):
        print(f"{folder}/")
        lines += [f"## {folder}", ""]
        for name, raw in files.items():
            with open(os.path.join(OUT_DIR, folder, name), "wb") as fh:
                fh.write(raw)
            print(f"  {len(raw):>9,}  {_sha256(raw)[:16]}  {name}")
            lines.append(f"- {len(raw)} -- `{_sha256(raw)}` -- `{name}` -- {sources[name]}")
        lines.append("")
    with open(os.path.join(OUT_DIR, "MANIFEST.md"), "w", encoding="utf-8", newline="\n") as fh:
        fh.write("\n".join(lines))
    with open(os.path.join(OUT_DIR, "README.md"), "w", encoding="utf-8", newline="\n") as fh:
        fh.write(f"# {ROUND}\n\n"
                 "**Nothing in here is uploaded by hand.** `docs/build/send_audit_round.py`\n"
                 f"sends `{MESSAGE1}/` as the first request (`--send`) and `{MESSAGE2}/`\n"
                 "as the second (`--send-part7`). Regenerate with\n"
                 "`python docs/build/build_round8_package.py`; do not edit anything in\n"
                 "here by hand. `MANIFEST.md` says where each file came from.\n")
    print(f"\n{len(message1) + len(message2)} files in two folders under {OUT_DIR}")


if __name__ == "__main__":
    main()
